alter table astronauts add column if not exists dia_regreso int not null default 180;

create table if not exists resultados_prueba (
  id uuid primary key default gen_random_uuid(),
  astronaut_id int not null,
  prueba_id text not null,
  valor jsonb default '{}'::jsonb,
  nivel text not null default 'ok',
  hecho_en timestamptz default now(),
  desde_ficha text
);
create index if not exists resultados_prueba_astronauta on resultados_prueba (astronaut_id, hecho_en);
alter table resultados_prueba enable row level security;
drop policy if exists hackathon_all on resultados_prueba;
create policy hackathon_all on resultados_prueba for all using (true) with check (true);
do $$ begin
  alter publication supabase_realtime add table resultados_prueba;
exception when duplicate_object then null;
end $$;

delete from resultados_prueba where valor->>'semilla' = 'si';
